const overlay=document.getElementById('overlay'),bodyEl=document.body,panelBody=document.getElementById('panelBody'),panelTitle=document.getElementById('panelTitle'),panelIcon=document.getElementById('panelIcon'),toast=document.getElementById('toast');let toastTimer;
/* محرك أصوات Web Audio API: لا يحتاج ملفات خارجية ويعمل بعد أول لمسة من المستخدم */
let audioCtx=null;
function audioReady(){if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}
function tone(freq,duration=.08,type='sine',volume=.035,delay=0){try{const c=audioReady(),o=c.createOscillator(),g=c.createGain(),t=c.currentTime+delay;o.type=type;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(60,freq*.82),t+duration);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(volume,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+duration+.02)}catch(e){}}
function soundTouch(){tone(520,.045,'sine',.025)}
function soundOpen(){tone(330,.07,'sine',.025);tone(520,.11,'sine',.025,.06)}
function soundSuccess(){tone(523,.1,'sine',.04);tone(659,.1,'sine',.04,.09);tone(784,.16,'sine',.045,.18)}
function soundError(){tone(190,.16,'sawtooth',.025);tone(130,.18,'sawtooth',.02,.1)}
function soundAtom(){tone(260,.07,'triangle',.025);tone(390,.1,'triangle',.03,.07)}
function soundParticle(kind,direction){const base=kind==='protons'?220:kind==='neutrons'?310:460;const shift=direction==='plus'?1.22:.78;tone(base*shift,.075,kind==='electrons'?'sine':'triangle',.04);tone(base*shift*1.45,.09,kind==='electrons'?'sine':'triangle',.028,.07)}
function soundActivityNumber(){tone(430,.06,'sine',.03);tone(650,.1,'sine',.028,.06)}
function soundDrag(){tone(250,.05,'triangle',.018)}
function soundReaction(){tone(180,.11,'square',.02);tone(360,.12,'triangle',.03,.1);tone(540,.18,'sine',.035,.22)}
