function openPanel(key){if(atomGL&&!atomXRSession)destroyAtomViewer();const p=panels[key];if(!p)return;panelTitle.textContent=p[0];panelIcon.className='fa-solid '+p[1];document.getElementById('atomHeaderTabs').innerHTML=key==='atom'?atomTabsMarkup():'';panelBody.innerHTML=p[2]();const footer=document.getElementById('panelFooterControls');if(footer)footer.innerHTML=key==='atom'?atomControls():'';overlay.classList.add('active');overlay.setAttribute('aria-hidden','false');bodyEl.classList.add('modal-open');document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.open===key));bind(key)}
function closePanel(){if(atomGL&&!atomXRSession)destroyAtomViewer();overlay.classList.remove('active');overlay.setAttribute('aria-hidden','true');bodyEl.classList.remove('modal-open');document.querySelectorAll('.nav-item').forEach(b=>b.classList.remove('active'))}
document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.open)));document.getElementById('closePanel').addEventListener('click',closePanel);overlay.addEventListener('click',e=>{if(e.target===overlay)closePanel()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closePanel()});
function getElement(){return elements[Math.min(elements.length-1,Math.max(0,state.protons-1))]}
function particles(type,count){return Array.from({length:Math.min(count,18)},()=>`<i class="particle ${type}"></i>`).join('')}
function periodic(){const pos={};const put=(z,row,col)=>pos[z]=[row,col];put(1,1,1);put(2,1,18);put(3,2,1);put(4,2,2);for(let z=5;z<=10;z++)put(z,2,z+8);put(11,3,1);put(12,3,2);for(let z=13;z<=18;z++)put(z,3,z);for(let z=19;z<=36;z++)put(z,4,z-18);for(let z=37;z<=54;z++)put(z,5,z-36);put(55,6,1);put(56,6,2);put(57,6,3);for(let z=72;z<=86;z++)put(z,6,z-68);put(87,7,1);put(88,7,2);put(89,7,3);for(let z=104;z<=118;z++)put(z,7,z-100);const focus=`<div class="periodic-focus embedded-focus"><span><small>العدد الذري</small><b>${state.protons}</b></span><strong>${getElement()[1]}</strong><span><small>النيوترونات</small><b>${state.neutrons}</b></span></div>`;return focus+Object.entries(pos).map(([z,rc])=>`<button class="element-cell ${Number(z)===state.protons?'active':''}" style="grid-column:${rc[1]};grid-row:${rc[0]}" data-periodic-z="${z}"><b>${periodicSymbols[Number(z)-1]||''}</b><small>${z}</small></button>`).join('')}
const periodicSymbols=['H','He','Li','Be','B','C','N','O','F','Ne','Na','Mg','Al','Si','P','S','Cl','Ar','K','Ca','Sc','Ti','V','Cr','Mn','Fe','Co','Ni','Cu','Zn','Ga','Ge','As','Se','Br','Kr','Rb','Sr','Y','Zr','Nb','Mo','Tc','Ru','Rh','Pd','Ag','Cd','In','Sn','Sb','Te','I','Xe','Cs','Ba','La','Ce','Pr','Nd','Pm','Sm','Eu','Gd','Tb','Dy','Ho','Er','Tm','Yb','Lu','Hf','Ta','W','Re','Os','Ir','Pt','Au','Hg','Tl','Pb','Bi','Po','At','Rn','Fr','Ra','Ac','Th','Pa','U','Np','Pu','Am','Cm','Bk','Cf','Es','Fm','Md','No','Lr','Rf','Db','Sg','Bh','Hs','Mt','Ds','Rg','Cn','Nh','Fl','Mc','Lv','Ts','Og'];
function nuclideChart(){let cells='';for(let z=10;z>=1;z--){for(let n=0;n<=12;n++){const visible=(n>=Math.max(0,z-3)&&n<=Math.min(12,z+4))||(z<=2&&n<=5);const stable=Math.abs(n-z)<=1;const active=z===state.protons&&n===state.neutrons;const type=stable?'stable':((n<z-1)?'proton':(n>z+2?'beta':'alpha'));cells+=`<button class="nuclide-cell ${visible?'':'blank'} ${type} ${active?'active':''}" data-nuclide-p="${z}" data-nuclide-n="${n}" title="بروتونات ${z} · نيوترونات ${n}">${active?getElement()[1]:''}</button>`}}return `<div class="nuclide-chart-wrap"><div class="nuclide-chart-title"><strong>مخطط النويات الجزئية</strong><small>تتغير الخلية والأرقام مع عدد الجسيمات</small></div><div class="nuclide-chart-body"><div class="nuclide-y-title">رقم البروتون</div><div class="nuclide-y-numbers">${Array.from({length:10},(_,i)=>{const z=10-i;return `<span class="${z===state.protons?'axis-active-proton':''}">${z}</span>`}).join('')}</div><div class="nuclide-chart-main"><div class="nuclide-x-numbers">${Array.from({length:13},(_,i)=>`<span class="${i===state.neutrons?'axis-active-neutron':''}">${i}</span>`).join('')}</div><div class="nuclide-grid">${cells}</div><div class="nuclide-x-title">رقم النيوترون →</div></div></div><div class="nuclide-readout"><span class="readout-proton">● بروتون: <b>${state.protons}</b></span><span class="readout-neutron">● نيوترون: <b>${state.neutrons}</b></span><span class="readout-electron">● إلكترون: <b>${state.electrons}</b></span></div><div class="nuclide-legend"><span><i class="stable"></i>مستقر</span><span><i class="alpha"></i>تحلل α</span><span><i class="beta"></i>تحلل β</span><span><i class="proton"></i>إشعاع بروتون</span></div></div>`}
function atomControls(){return `<div class="atom-controls"><div class="control-unit"><div class="control-buttons"><button class="mini-btn" data-count="protons" data-step="-1">−</button><b>${state.protons}</b><button class="mini-btn gold" data-count="protons" data-step="1">+</button></div><span class="control-name"><i class="fa-solid fa-circle-plus proton-icon"></i> بروتون</span></div><div class="control-unit"><div class="control-buttons"><button class="mini-btn" data-count="neutrons" data-step="-1">−</button><b>${state.neutrons}</b><button class="mini-btn gold" data-count="neutrons" data-step="1">+</button></div><span class="control-name"><i class="fa-solid fa-circle neutron-icon"></i> نيوترون</span></div><div class="control-unit"><div class="control-buttons"><button class="mini-btn" data-count="electrons" data-step="-1">−</button><b>${state.electrons}</b><button class="mini-btn gold" data-count="electrons" data-step="1">+</button></div><span class="control-name"><i class="fa-solid fa-bolt electron-icon"></i> إلكترون</span></div></div>`}
function electronParticles(){let out='';const total=Math.min(state.electrons,20);for(let i=0;i<total;i++){const angle=(360/Math.max(1,total))*i;const radius=i<2?86:124;out+=`<i class="orbit-electron" style="transform:rotate(${angle}deg) translateX(${radius}px)"></i>`}return out}
function atomSphere(){const [name,symbol]=getElement(),charge=state.protons-state.electrons,mass=state.protons+state.neutrons;return `<div class="model-card atom-model-card" id="modelCard"><div class="model-stage"><div class="molecule" id="molecule" style="transform:rotateX(${state.model.x}deg) rotateY(${state.model.y}deg) scale(${state.model.scale})"><div class="atom-cluster model-cluster">${clusterParticles()}</div>${electronParticles()}<div class="molecule-ring"></div><div class="molecule-ring r2"></div><div class="molecule-ring r3"></div><div class="molecule-core">${symbol}</div></div></div><div class="zoom-controls"><button id="zoomIn" aria-label="تكبير"><i class="fa-solid fa-plus"></i></button><button id="zoomOut" aria-label="تصغير"><i class="fa-solid fa-minus"></i></button><button id="resetModel" aria-label="إعادة الضبط"><i class="fa-solid fa-rotate"></i></button></div><div class="atom-model-label"><strong>${name} · ${symbol}</strong><small>العدد الكتلي ${mass} · الشحنة ${charge>0?'+':''}${charge}</small></div></div>`}
function clusterParticles(){const out=[];let index=0;const coords=[[0,0,0],[-18,-12,10],[18,-12,-8],[-22,14,-4],[22,14,7],[0,24,18],[0,-25,-18],[-28,0,8],[28,0,-9],[-12,4,25],[12,4,-25],[-6,-20,20],[6,20,-20],[-30,-16,-12],[30,16,12],[-16,26,3],[16,-26,-3],[-35,8,0],[35,-8,0]];for(let i=0;i<state.protons && index<coords.length;i++,index++){const c=coords[index];out.push(`<i class="cluster-particle cp" style="transform:translate3d(${c[0]}px,${c[1]}px,${c[2]}px)"></i>`)}for(let i=0;i<state.neutrons && index<coords.length;i++,index++){const c=coords[index];out.push(`<i class="cluster-particle cn" style="transform:translate3d(${c[0]}px,${c[1]}px,${c[2]}px)"></i>`)}return out.join('')}
function atomFacts(){const [name,symbol]=getElement(),charge=state.protons-state.electrons,mass=state.protons+state.neutrons;return `<div class="fact-strip"><div class="fact"><b>${state.protons}</b><small>عدد ذري</small></div><div class="fact"><b>${mass}</b><small>عدد كتلي</small></div><div class="fact"><b>${symbol}</b><small>${name}</small></div><div class="fact"><b>${charge>0?'+':''}${charge}</b><small>الشحنة</small></div></div>`}
function activityHeading(title,description){return `<div class="activity-heading"><h4>${title}</h4><p>${description}</p></div>`}
