 '1-0':'stable','1-1':'stable','1-2':'beta',
 '2-1':'stable','2-2':'stable',
 '3-3':'stable','3-4':'stable','3-5':'beta',
 '4-3':'positron','4-4':'alpha','4-5':'stable','4-6':'beta',
 '5-5':'stable','5-6':'stable','5-7':'beta',
 '6-5':'positron','6-6':'stable','6-7':'stable','6-8':'beta',
 '7-6':'positron','7-7':'stable','7-8':'stable','7-9':'beta',
