function elementNameOrSymbol(z){return z>=1&&z<=20?elements[z-1][0]:periodicSymbols[z-1]}
/* الجدول الدوري يطابق تخطيط المجموعات 1–18 والفترات 1–7، مع إظهار الصفوف الرئيسية. */
function periodic(){
 const spots=[];const put=(z,row,col)=>spots.push({z,row,col});put(1,1,1);put(2,1,18);
 for(let z=3;z<=10;z++){let row=2,col=z<=4?z-2:z+8;put(z,row,col)}
 for(let z=11;z<=18;z++){let row=3,col=z<=12?z-10:z;put(z,row,col)}
 for(let z=19;z<=36;z++)put(z,4,z-18);
 for(let z=37;z<=54;z++)put(z,5,z-36);
 put(55,6,1);put(56,6,2);put(57,6,3);
 for(let z=72;z<=86;z++)put(z,6,z-68);
 put(87,7,1);put(88,7,2);put(89,7,3);
 for(let z=104;z<=118;z++)put(z,7,z-100);
 const cells=spots.map(({z,row,col})=>`<button class="element-cell ${z===state.protons?'active':''}" data-periodic-z="${z}" style="grid-column:${col};grid-row:${row}" title="${elementNameOrSymbol(z)} · ${z}${z<=20?' · حدده':' · مرجع'}" ${z>20?'disabled aria-disabled="true"':''}><b>${periodicSymbols[z-1]}</b></button>`).join('');
 return cells;
}
function chartSVGline(value,max=20,label=''){
 const end=635,start=35,w=end-start,pos=start+Math.max(0,Math.min(1,value/max))*w;
 return `<svg class="inline-chart" viewBox="0 0 670 102" role="img" aria-label="${label}: ${value}"><line x1="${start}" y1="46" x2="${end}" y2="46" stroke="#0b1d33" stroke-width="3"/><path d="M ${end} 46 l -12 -7 v 14z" fill="#0b1d33"/>${Array.from({length:max+1},(_,n)=>{let x=start+n*w/max;return `<line x1="${x}" y1="40" x2="${x}" y2="53" stroke="#87919a" stroke-width="1.4"/>${n%Math.max(1,Math.ceil(max/10))===0?`<text x="${x}" y="72" fill="#687687" text-anchor="middle" font-size="10">${n}</text>`:''}`}).join('')}<circle cx="${pos}" cy="46" r="10" fill="#bd9540" stroke="#065952" stroke-width="3"/><text x="${pos}" y="22" text-anchor="middle" font-weight="bold" fill="#065952" font-size="14">${value}</text></svg>`;
}
function nuclideChart(){
 let cells='';for(let z=10;z>=1;z--){for(let n=0;n<=15;n++){
 const key=`${z}-${n}`,kind=NUCLIDE_PLOT[key],active=z===state.protons&&n===state.neutrons;
 cells+=`<button class="nuclide-cell ${kind||'empty'} ${active?'active':''}" ${kind?'':`disabled aria-disabled="true"`} data-nuclide-p="${z}" data-nuclide-n="${n}" aria-label="${periodicSymbols[z-1]}-${z+n}: ${kind?NUCLEUS_LABELS[kind]:'بيانات غير معروضة'}" title="${periodicSymbols[z-1]}-${z+n}: ${NUCLEUS_LABELS[kind]||'غير مدرج'}">${active?periodicSymbols[z-1]:''}</button>`;
 }}
 const current=NUCLIDE_PLOT[`${state.protons}-${state.neutrons}`];
 return `<div class="nuclide-chart-wrap"><div class="nuclide-chart-title"><strong>مخطط النويات</strong><small>أمثلة محددة ذات بيانات معروفة</small></div><div class="nuclide-chart-body"><div class="nuclide-y-title">رقم البروتون</div><div class="nuclide-y-numbers">${Array.from({length:10},(_,i)=>`<span class="${10-i===state.protons?'axis-active-proton':''}">${10-i}</span>`).join('')}</div><div class="nuclide-chart-main"><div class="nuclide-x-numbers">${Array.from({length:16},(_,i)=>`<span class="${i===state.neutrons?'axis-active-neutron':''}">${i}</span>`).join('')}</div><div class="nuclide-grid">${cells}</div><div class="nuclide-x-title">رقم النيوترون →</div></div></div><div class="nuclide-legend"><span><i class="stable"></i>مستقر</span><span><i class="beta"></i>بيتا −</span><span><i class="positron"></i>بيتا + / التقاط إلكترون</span><span><i class="alpha"></i>ألفا</span></div><p class="activity-quiet" id="chartInfo">${current?`النظير المختار: ${atomIdentity().symbol}-${state.protons+state.neutrons} · ${NUCLEUS_LABELS[current]}`:'النظير الحالي خارج الأمثلة المعروضة؛ لا يُستنتج الاستقرار من موقعه وحده.'}</p></div>`;
}
function isotopeTrackMarkup(z=state.protons,n=state.neutrons){const total=z+n,ratio=Math.min(1,z/20),x=30+Math.min(20,z)/20*570,xx=30+Math.min(30,n)/30*570;return `<div class="nuclear-track"><h4>مقارنة أعداد الجسيمات في النواة</h4><div class="nuclide-stats"><div><b>${z}</b><small>بروتونات Z</small></div><div><b>${n}</b><small>نيوترونات N</small></div><div><b>${total}</b><small>العدد الكتلي A</small></div></div><div><strong>البروتونات</strong>${chartSVGline(z,20,'البروتونات')}<strong>النيوترونات</strong>${chartSVGline(n,30,'النيوترونات')}</div></div>`}
function halfCurveMarkup(n){const plotX=56,plotY=22,width=568,height=175,pointX=plotX+n*width/8,pointY=plotY+height*(1-Math.pow(.5,n));let path='';for(let i=0;i<=80;i++){const step=i/10;const x=plotX+step*width/8,y=plotY+height*(1-Math.pow(.5,step));path+=(i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)+' '}
 return `<div class="nuclear-track"><h4>منحنى النسبة المتبقية من العينة</h4><svg viewBox="0 0 690 256" role="img" aria-label="منحنى العمر النصفي، عند الفترة ${n} يتبقى ${(100*Math.pow(.5,n)).toFixed(2)} بالمئة"><line x1="${plotX}" y1="${plotY}" x2="${plotX}" y2="${plotY+height}" stroke="#0b1d33" stroke-width="2"/><line x1="${plotX}" y1="${plotY+height}" x2="${plotX+width+10}" y2="${plotY+height}" stroke="#0b1d33" stroke-width="2"/>${[0,25,50,75,100].map(p=>`<line x1="${plotX}" y1="${plotY+height-p/100*height}" x2="${plotX+width}" y2="${plotY+height-p/100*height}" stroke="#cfd6dc" stroke-dasharray="3,5"/><text x="${plotX-9}" y="${plotY+height-p/100*height+4}" text-anchor="end">${p}%</text>`).join('')}${Array.from({length:9},(_,i)=>`<text x="${plotX+i*width/8}" y="${plotY+height+19}" text-anchor="middle">${i}</text>`).join('')}<path d="${path}" fill="none" stroke="#065952" stroke-width="5" stroke-linecap="round"/><line x1="${pointX}" y1="${pointY}" x2="${pointX}" y2="${plotY+height}" stroke="#bd9540" stroke-width="3" stroke-dasharray="4,4"/><circle cx="${pointX}" cy="${pointY}" r="10" fill="#bd9540" stroke="#fff" stroke-width="3"/><text x="${Math.max(60,Math.min(605,pointX))}" y="${Math.max(15,pointY-15)}" font-size="14" text-anchor="middle" font-weight="bold">${(100*Math.pow(.5,n)).toFixed(n<3?1:2)}%</text><text x="${plotX+width/2}" y="${plotY+height+42}" text-anchor="middle">عدد فترات العمر النصفي</text></svg><input id="halfRange" type="range" min="0" max="8" step="1" value="${n}" aria-label="عدد فترات العمر النصفي"/><div class="range-numbers"><span>0</span><span>1</span><span>2</span><span>3</span><span>4</span><span>5</span><span>6</span><span>7</span><span>8</span></div></div>`}
const NUCLEAR_DECAYS={alpha:{z1:92,n1:146,z2:90,n2:144,a1:238,a2:234,start:'²³⁸U',end:'²³⁴Th',particle:'⁴He',explain:'تنقص البروتونات بمقدار 2 والنيوترونات بمقدار 2؛ ينقص العدد الكتلي 4.'},beta:{z1:6,n1:8,z2:7,n2:7,a1:14,a2:14,start:'¹⁴C',end:'¹⁴N',particle:'e⁻ + ν̄ₑ',explain:'يتحوّل نيوترون إلى بروتون؛ يبقى العدد الكتلي ثابتًا ويزداد العدد الذري واحدًا.'},gamma:{z1:43,n1:56,z2:43,n2:56,a1:99,a2:99,start:'⁹⁹ᵐTc',end:'⁹⁹Tc',particle:'γ',explain:'تصدر النواة فوتون غاما وتنخفض طاقتها دون تغير أعداد البروتونات أو النيوترونات.'}};
function decayFlowMarkup(kind){const d=NUCLEAR_DECAYS[kind];return `<div class="nuclear-track"><h4>قبل التحلل وبعده</h4><div class="reaction-row"><div><small>قبل</small><div class="formula">${d.start}</div><small>Z=${d.z1} | N=${d.n1}</small></div><div class="plus">→</div><div><small>بعد</small><div class="formula">${d.end}</div><small>Z=${d.z2} | N=${d.n2}</small></div></div><div class="nuclide-stats"><div><b>${d.z2-d.z1>0?'+':''}${d.z2-d.z1}</b><small>Δ البروتون</small></div><div><b>${d.n2-d.n1>0?'+':''}${d.n2-d.n1}</b><small>Δ النيوترون</small></div><div><b>${d.a2-d.a1>0?'+':''}${d.a2-d.a1}</b><small>Δ العدد الكتلي</small></div></div><p class="activity-quiet">${d.explain} الجسيم المنبعث: ${d.particle}.</p></div>`}
function renderAtomActivityNew(){const x=atomIdentity(),h=t=>activityHeading(t,''),plot=NUCLIDE_PLOT[`${x.z}-${state.neutrons}`];
 if(state.atomActivity===1)return `${h('بناء الذرة واستوديو الواقع المعزز')}<div class="subcard activity-main atom-single-card">${atomSceneNew()}${atomFactsNew()}</div>`;
 if(state.atomActivity===2)return `${h('الجدول الدوري التفاعلي')}<div class="subcard activity-main atom-single-card"><div class="periodic-wrap periodic-expanded"><div class="periodic">${periodic()}</div></div><div class="periodic-foot"><span><strong>${x.name}</strong> · اختر عنصرًا من العناصر العشرين الأولى</span><span>العدد الذري Z = ${x.z} | A = ${x.a} | الشحنة ${x.sign}</span></div>${isotopeTrackMarkup()}</div>`;
 if(state.atomActivity===3)return `${h('مخطط النويات والاستقرار النووي')}<div class="subcard activity-main atom-single-card"><p class="activity-quiet">قسم إثرائي مستقل عن الروابط الكيميائية. الألوان تعبر عن أمثلة محددة فقط، لا عن تنبؤ باستقرار أي نواة جديدة.</p>${nuclideChart()}${isotopeTrackMarkup()}<div class="stability"><strong>${x.known?x.known.name+' · '+x.known.status:plot?`${x.symbol}-${x.a} · ${NUCLEUS_LABELS[plot]}`:`${x.symbol}-${x.a} · بيانات غير مدرجة`}</strong><p class="activity-quiet">${x.known?x.known.half?'العمر النصفي: '+x.known.half:'لم يثبت له تحلل إشعاعي في مجموعة الأمثلة.':'اختَر خلية ملونة لمعرفة نوع استقرار النظير أو تحلله.'}</p></div></div>`;
 if(state.atomActivity===4)return `${h('النظائر وأنواع التحلل')}<div class="subcard activity-main atom-single-card"><div class="two-col"><div class="subcard"><h4>اختيار النظير</h4><select class="isotope-select" id="isotopeSelect"><option value="">اختَر نظيرًا</option>${Object.entries(VERIFIED_NUCLIDES).map(([k,r])=>`<option value="${k}" ${`${state.protons}-${state.neutrons}`===k?'selected':''}>${r.name}</option>`).join('')}</select>${isotopeTrackMarkup()}</div><div class="subcard"><h4>نوع التحلل</h4><div class="decay-tabs">${[['alpha','ألفا α'],['beta','بيتا −'],['gamma','غاما γ']].map(([k,l])=>`<button class="decay-tab ${state.decay===k?'active':''}" data-decay="${k}">${l}</button>`).join('')}</div><div id="decayInfo">${decayFlowMarkup(state.decay)}</div></div></div></div>`;
 const key=NUCLEAR_EXAMPLES.some(r=>r[0]===state.halfChoice)?state.halfChoice:'1-2', info=VERIFIED_NUCLIDES[key],n=state.halfSteps||0,pct=100*Math.pow(.5,n);
 return `${h('العمر النصفي')}<div class="subcard atom-single-card half-life-lab"><div class="half-life-header"><div><strong>${info.name}</strong><small>العمر النصفي: ${info.half}</small></div><div class="isotope-card"><b>النسبة المتبقية</b><strong id="halfPct">${Number(pct.toFixed(2))}%</strong></div></div><select class="isotope-select" id="halfIsotope">${NUCLEAR_EXAMPLES.map(([k,label])=>`<option value="${k}" ${k===key?'selected':''}>${label}</option>`).join('')}</select>${halfCurveMarkup(n)}<div class="reaction-controls"><button class="experiment-btn" id="halfPrev" ${n===0?'disabled':''}>− فترة</button><button class="experiment-btn" id="halfNext" ${n===8?'disabled':''}>+ فترة</button><button class="experiment-btn" id="halfReset">إعادة</button></div><p class="activity-quiet">النسبة المتبقية في عينة كبيرة بعد n فترات = 100 × (½)ⁿ. هذا وصف إحصائي لا موعد لتحلل نواة واحدة.</p></div>`;
}
/* إنشاء نموذج كيميائي من كرات وروابط ثلاثية الأبعاد، مع تجميع ذرات التفاعل دون خرق قانون حفظ الذرات. */
function chemShiftedCopies(parts){const atoms=[],bonds=[];for(const [name,dx,dy,dz] of parts){const m=CHEM_MODELS[name];if(!m)continue;const base=atoms.length;for(const a of m.atoms)atoms.push([a[0],a[1]+dx,a[2]+dy,a[3]+dz]);for(const [a,b,c] of m.bonds)bonds.push([a+base,b+base,c])}return {atoms,bonds}}
CHEM_MODELS.Na={name:'ذرة صوديوم Na',atoms:[['Na',0,0,0]],bonds:[]};
CHEM_MODELS.Cl2={name:'كلور Cl₂',atoms:[['Cl',-.65,0,0],['Cl',.65,0,0]],bonds:[[0,1,1]]};
CHEM_MODELS.waterBefore={name:'قبل تكوين الماء',...chemShiftedCopies([['H2',-2,1,0],['H2',-2,-1,0],['O2',1.7,0,0]])};
CHEM_MODELS.waterAfter={name:'بعد تكوين الماء',...chemShiftedCopies([['H2O',-1.65,0,0],['H2O',1.65,0,0]])};
CHEM_MODELS.saltBefore={name:'قبل التفاعل',...chemShiftedCopies([['Na',-2.2,.65,0],['Na',-2.2,-.65,0],['Cl2',1,0,0]])};
CHEM_MODELS.saltAfter=CHEM_MODELS.NaCl;
CHEM_MODELS.combustionBefore={name:'قبل الاحتراق',...chemShiftedCopies([['CH4',-2,0,0],['O2',1.5,1,0],['O2',1.5,-1,0]])};
CHEM_MODELS.combustionAfter={name:'بعد الاحتراق',...chemShiftedCopies([['CO2',-1.6,0,0],['H2O',1.5,1,0],['H2O',1.5,-1,0]])};
let chemGPU=null,chemRAF=0,chemPointer=null,chemXRSession=null,chemXRRef=null,chemXRHit=null,chemXRHitPose=null,chemXRPlaced=null,chemXRScale=1;
state.chemAngle ||= {x:-.26,y:.43,zoom:1};
function chemDestroy(){if(chemRAF)cancelAnimationFrame(chemRAF);chemRAF=0;chemPointer=null;if(!chemXRSession&&chemGPU){try{chemGPU.gl.getExtension('WEBGL_lose_context')?.loseContext()}catch{}}chemGPU=null}
function chemCurrentKey(){const sel=document.getElementById('chemCanvas');return sel?.dataset.model||'H2O'}
function chemDraw(){if(!chemGPU||chemXRSession||!document.getElementById('chemCanvas'))return;const s=chemGPU,g=s.gl,r=s.canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2),w=Math.max(1,Math.round(r.width*d)),h=Math.max(1,Math.round(r.height*d));if(s.canvas.width!==w||s.canvas.height!==h){s.canvas.width=w;s.canvas.height=h}g.bindFramebuffer(g.FRAMEBUFFER,null);g.viewport(0,0,w,h);g.enable(g.DEPTH_TEST);g.disable(g.CULL_FACE);g.clearColor(.037,.125,.19,1);g.clear(g.COLOR_BUFFER_BIT|g.DEPTH_BUFFER_BIT);const key=chemCurrentKey(),m=CHEM_MODELS[key],wide=m?.atoms.length>8||key.endsWith('Before')||key.endsWith('After'),z=wide?10:5.2,scale=(wide?.90:1)*state.chemAngle.zoom;chemDrawMolecule(s,chemPerspective(Math.PI/3,w/h,.01,100),chemTr(0,0,-z),chemMm(chemRy(state.chemAngle.y),chemMm(chemRx(state.chemAngle.x),chemSc(scale,scale,scale))),key);chemRAF=requestAnimationFrame(chemDraw)}
function chemMount(){const c=document.getElementById('chemCanvas');if(!c)return;try{chemGPU=chemCreateGL(c);c.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;chemPointer={id:e.pointerId,x:e.clientX,y:e.clientY};c.setPointerCapture?.(e.pointerId)});c.addEventListener('pointermove',e=>{if(!chemPointer||chemPointer.id!==e.pointerId)return;state.chemAngle.y+=(e.clientX-chemPointer.x)*.012;state.chemAngle.x+=(e.clientY-chemPointer.y)*.012;chemPointer.x=e.clientX;chemPointer.y=e.clientY});for(const t of ['pointerup','pointercancel','lostpointercapture'])c.addEventListener(t,()=>chemPointer=null);c.addEventListener('wheel',e=>{e.preventDefault();state.chemAngle.zoom=Math.max(.6,Math.min(1.9,state.chemAngle.zoom+(e.deltaY<0?.08:-.08)))},{passive:false});chemDraw()}catch(e){const f=document.getElementById('chemFallback');if(f){f.style.display='flex';f.textContent='تعذّر عرض المجسم ثلاثي الأبعاد على هذا الجهاز.'}}}
function chemSceneHTML(model,label){return `<div class="chem-model-card"><canvas id="chemCanvas" data-model="${model}" aria-label="مجسم تفاعلي ثلاثي الأبعاد: ${escapeChem(label)}"></canvas><div class="chem-fallback" id="chemFallback"></div><div class="chem-scene-badge" id="chemSceneBadge">${escapeChem(label)}</div></div><div class="chem-model-readout"><strong>${escapeChem(label)}</strong><div class="reaction-controls"><button class="experiment-btn" id="chemARStart" type="button">عرض AR</button><button class="primary-btn" id="chemResetView" type="button">إعادة العرض</button></div></div>`}
function chemSetModel(model,label){const c=document.getElementById('chemCanvas');if(c)c.dataset.model=model;const b=document.getElementById('chemSceneBadge');if(b)b.textContent=label;const read=b?.parentElement?.nextElementSibling?.querySelector('strong');if(read)read.textContent=label;}
const chemOriginalOpenPanel=openPanel;
openPanel=function(key){if(chemGPU&&!chemXRSession)chemDestroy();chemOriginalOpenPanel(key);if(['ionic','covalent','reaction'].includes(key))chemMount();};
const chemOriginalClosePanel=closePanel;
closePanel=function(){if(chemGPU&&!chemXRSession)chemDestroy();chemOriginalClosePanel()};
function chemBindShared(){document.getElementById('chemResetView')?.addEventListener('click',()=>{state.chemAngle={x:-.26,y:.43,zoom:1}});document.getElementById('chemARStart')?.addEventListener('click',chemStartAR)}
/* الرابطة الأيونية: انتقال إلكترون من ذرتين متعادلتين ثم تجاذب داخل شبكة. */
function renderIonicNew(){const done=!!state.ionicDone;return `<div class="two-col chem-lab-columns"><div class="subcard"><h4>انتقال إلكترون التكافؤ</h4><div class="electron-line"><div class="e-orb" id="ionicNa">${done?'Na⁺':'Na'}</div><div class="electron-track ${done?'done':''}" id="ionicTrack"><span class="moving-e" aria-hidden="true">e⁻</span></div><div class="e-orb" id="ionicCl" style="background:var(--gold);color:var(--navy)">${done?'Cl⁻':'Cl'}</div></div><div class="nuclide-stats"><div><b>Na ${done?'2،8':'2،8،1'}</b><small>الإلكترونات</small></div><div><b>Cl ${done?'2،8،8':'2،8،7'}</b><small>الإلكترونات</small></div><div><b>${done?'Na⁺ / Cl⁻':'Na / Cl'}</b><small>الشحنات</small></div></div><div class="reaction-controls"><button class="experiment-btn" id="transferBtn">${done?'إعادة التجربة':'نقل الإلكترون'}</button></div><div class="stability"><strong>${done?'تكونت الأيونات':'ذرتان متعادلتان'}</strong><p class="activity-quiet">${done?'يفقد الصوديوم إلكترونًا ويكتسبه الكلور؛ تتجاذب الأيونات ولا تتكون جزيئات NaCl مستقلة في البلورة.':'لا يتغير عدد البروتونات. نقل إلكترون واحد يغير الشحنة والتوزيع الإلكتروني.'}</p></div></div><div class="subcard"><h4>استوديو الواقع المعزز</h4>${chemSceneHTML(done?'NaCl':'saltBefore',done?'ترتيب أيوني متكرر':'قبل انتقال الإلكترون')}<p class="activity-quiet">الكرات تمثل أيونات متناوبة في جزء صغير من البلورة؛ لا نرسم روابط تساهمية بين Na⁺ وCl⁻.</p></div></div>`}
function bindIonicNew(){chemBindShared();document.getElementById('transferBtn')?.addEventListener('click',()=>{state.ionicDone=!state.ionicDone;soundSuccess();openPanel('ionic')})}
/* التساهمية: نسب صحيحة للروابط الأحادية والثنائية والثلاثية والجزيئات المتعددة. */
function renderCovalentNew(){const key=state.covalentModel||'H2',m=CHEM_MODELS[key]||CHEM_MODELS.H2,examples=['H2','O2','N2','H2O','CH4','CO2'];return `<div class="two-col chem-lab-columns"><div class="subcard"><h4>اختيار الجزيء</h4><div class="chem-model-pick">${examples.map(k=>`<button class="${k===key?'active':''}" data-cov-model="${k}">${CHEM_MODELS[k].name}</button>`).join('')}</div><div class="stability"><strong id="covTitle">${m.name}</strong><p class="activity-quiet">${m.explain}</p></div><h4>اختبار الروابط في الجزيء</h4><p class="activity-quiet">اختر عدد أزواج الإلكترونات المشتركة في الرابطة الممثلة.</p><div class="bond-stepper">${[1,2,3].map(n=>`<button data-pairs="${n}">${n===1?'زوج واحد':n===2?'زوجان':'ثلاثة أزواج'}</button>`).join('')}</div><div class="result-banner" id="covalentResult" aria-live="polite"></div><div class="nuclear-track"><h4>عدد أزواج الإلكترونات المشتركة</h4>${chartSVGline(m.bonds[0]?.[2]||1,3,'أزواج إلكترونية')}${key==='CH4'?'<p class="activity-quiet">الميثان يتضمن أربع روابط أحادية C–H، وليست رابطة رباعية.</p>':''}</div></div><div class="subcard"><h4>استوديو الواقع المعزز</h4>${chemSceneHTML(key,m.name)}<p class="activity-quiet">${m.lewis} · الكرات ذرات، والوصلات تمثل روابط تساهمية تعليمية.</p></div></div>`}
function bindCovalentNew(){chemBindShared();document.querySelectorAll('[data-cov-model]').forEach(b=>b.addEventListener('click',()=>{state.covalentModel=b.dataset.covModel;soundOpen();openPanel('covalent')}));document.querySelectorAll('[data-pairs]').forEach(b=>b.addEventListener('click',()=>{const m=CHEM_MODELS[state.covalentModel||'H2'],chosen=Number(b.dataset.pairs),correct=m.bonds[0]?.[2]||1,box=document.getElementById('covalentResult');document.querySelectorAll('[data-pairs]').forEach(x=>x.classList.toggle('active',x===b));box.classList.add('show');box.textContent=chosen===correct?`صحيح: الرابطة المختارة تشارك ${correct} ${correct===1?'زوجًا':'أزواج'} من الإلكترونات.`:`حاول مرة أخرى؛ الرابطة المختارة تشارك ${correct} ${correct===1?'زوجًا':'أزواج'} من الإلكترونات.`;box.style.color=chosen===correct?'var(--green)':'var(--red)';chosen===correct?soundSuccess():soundError()}))}
/* مختبر التفاعلات: معاملات قابلة للتعديل + حفظ الذرات + مجسم قبل/بعد. */
const REACTION_SPEC={
 salt:{left:['Na','Cl₂'],right:['NaCl'],componentsLeft:[{Na:1},{Cl:2}],componentsRight:[{Na:1,Cl:1}],expected:[2,1,2],elements:['Na','Cl'],models:['saltBefore','saltAfter']},
 water:{left:['H₂','O₂'],right:['H₂O'],componentsLeft:[{H:2},{O:2}],componentsRight:[{H:2,O:1}],expected:[2,1,2],elements:['H','O'],models:['waterBefore','waterAfter']},
 combustion:{left:['CH₄','O₂'],right:['CO₂','H₂O'],componentsLeft:[{C:1,H:4},{O:2}],componentsRight:[{C:1,O:2},{H:2,O:1}],expected:[1,2,1,2],elements:['C','H','O'],models:['combustionBefore','combustionAfter']}
};
function rxSpec(){return REACTION_SPEC[state.reactionType||'salt']}
function rxCoeffs(){const v=state.reactionType||'salt',sp=rxSpec();state.rxCoeffs||={};if(!Array.isArray(state.rxCoeffs[v]))state.rxCoeffs[v]=Array(sp.expected.length).fill(1);return state.rxCoeffs[v]}
function rxTotals(){const sp=rxSpec(),cs=rxCoeffs(),left={},right={};sp.componentsLeft.forEach((part,i)=>{for(const [atom,n] of Object.entries(part))left[atom]=(left[atom]||0)+cs[i]*n});sp.componentsRight.forEach((part,i)=>{for(const [atom,n] of Object.entries(part))right[atom]=(right[atom]||0)+cs[i+sp.componentsLeft.length]*n});return {left,right,balanced:sp.elements.every(el=>left[el]===right[el])}}
function rxEquation(){const sp=rxSpec(),coef=rxCoeffs(),n=sp.componentsLeft.length;return `<div class="formula" style="font-size:clamp(1.05rem,3vw,1.7rem)">${sp.left.map((name,i)=>(coef[i]===1?'':coef[i])+name).join(' + ')}</div><div class="plus">⟶</div><div class="formula" style="font-size:clamp(1.05rem,3vw,1.7rem)">${sp.right.map((name,i)=>(coef[i+n]===1?'':coef[i+n])+name).join(' + ')}</div>`}
function rxBalanceChart(){const sp=rxSpec(),t=rxTotals(),max=Math.max(1,...sp.elements.flatMap(x=>[t.left[x]||0,t.right[x]||0]));return `<div class="balance-rows">${sp.elements.map(el=>{const a=t.left[el]||0,b=t.right[el]||0;return `<div class="balance-row"><strong>${el}</strong><div class="balance-bars"><span class="reactant" style="width:${a/max*48}%" title="المتفاعلات ${a}"></span><span class="product" style="width:${b/max*48}%" title="النواتج ${b}"></span></div><small>${a} = ${b} ${a===b?'✓':'×'}</small></div>`}).join('')}</div><p class="activity-quiet"><span style="color:var(--gold)">■</span> المتفاعلات <span style="color:var(--green)">■</span> النواتج · ارفع أو اخفض المعاملات حتى تتساوى أعداد كل عنصر.</p>`}
function rxStepper(){const sp=rxSpec(),coef=rxCoeffs(),labels=[...sp.left,...sp.right];return `<div class="balance-steps">${labels.map((label,i)=>`<div class="stepper-unit"><small>${label}</small><button data-rx-i="${i}" data-rx-step="-1" ${coef[i]===1?'disabled':''}>−</button><b>${coef[i]}</b><button data-rx-i="${i}" data-rx-step="1">+</button></div>`).join('')}</div>`}
function renderReactionNew(){const v=state.reactionType||'salt',sp=rxSpec(),t=rxTotals(),stage=state.rxStage||0;const model=sp.models[stage===0?0:1],eq=CHEM_REACTIONS[v];return `<div class="two-col chem-lab-columns"><div class="subcard"><h4>موازنة المعادلة</h4><select class="select-control" id="reactionSelect">${Object.entries(CHEM_REACTIONS).map(([k,r])=>`<option value="${k}" ${v===k?'selected':''}>${r.name}</option>`).join('')}</select><div id="reactionEquation" class="reaction-row" style="margin-top:13px">${rxEquation()}</div><div id="rxCoefControls">${rxStepper()}</div><div id="rxCompare">${rxBalanceChart()}</div><div class="result-banner show" id="rxBalanceResult" style="display:block;color:${t.balanced?'var(--green)':'var(--navy)'}">${t.balanced?'المعادلة موزونة: الذرات محفوظة على جانبي المعادلة.':'غيّر المعاملات حتى تتساوى الذرات على جانبي المعادلة.'}</div><div class="reaction-controls"><button class="experiment-btn" id="rxSetCorrect">اعرض الموازنة الصحيحة</button><button class="primary-btn" id="rxReset">إعادة المحاولة</button></div></div><div class="subcard"><h4>استوديو الواقع المعزز</h4><div class="bond-stepper"><button data-rx-stage="0" class="${stage===0?'active':''}">المتفاعلات</button><button data-rx-stage="1" class="${stage===1?'active':''}">تغيّر الروابط</button><button data-rx-stage="2" class="${stage===2?'active':''}">النواتج</button></div>${chemSceneHTML(model,stage===0?'قبل التفاعل':stage===1?'تمثيل انتقال بين حالتين':'بعد التفاعل')}<div class="stability"><strong>${stage===0?'جزيئات وذرات المتفاعلات':stage===1?'إعادة ترتيب الذرات':v==='salt'?'شبكة أيونية متكررة':'جزيئات النواتج'}</strong><p class="activity-quiet">${stage===1?'يمثل هذا الانتقال تغير ترتيب الروابط بصورة تعليمية، وليس المسار الزمني الحقيقي للتفاعل.':stage===0?'احسب الذرات قبل بدء التفاعل، ثم انتقل إلى المرحلة التالية.':eq.steps[2]}</p></div></div></div>`}
function bindReactionNew(){chemBindShared();document.getElementById('reactionSelect')?.addEventListener('change',e=>{state.reactionType=e.target.value;state.rxStage=0;openPanel('reaction')});document.querySelectorAll('[data-rx-i]').forEach(b=>b.addEventListener('click',()=>{const i=+b.dataset.rxI,s=+b.dataset.rxStep,c=rxCoeffs();c[i]=Math.max(1,Math.min(9,c[i]+s));refreshReactionNumbers()}));document.getElementById('rxSetCorrect')?.addEventListener('click',()=>{state.rxCoeffs[state.reactionType||'salt']=rxSpec().expected.slice();refreshReactionNumbers();soundSuccess()});document.getElementById('rxReset')?.addEventListener('click',()=>{state.rxCoeffs[state.reactionType||'salt']=Array(rxSpec().expected.length).fill(1);refreshReactionNumbers()});document.querySelectorAll('[data-rx-stage]').forEach(b=>b.addEventListener('click',()=>{state.rxStage=+b.dataset.rxStage;openPanel('reaction')}))}
function refreshReactionNumbers(){const t=rxTotals(),ele=id=>document.getElementById(id),eq=ele('reactionEquation'),c=ele('rxCoefControls'),chart=ele('rxCompare'),status=ele('rxBalanceResult');if(eq)eq.innerHTML=rxEquation();if(c)c.innerHTML=rxStepper();if(chart)chart.innerHTML=rxBalanceChart();if(status){status.textContent=t.balanced?'صحيح: تساوى عدد الذرات في طرفي المعادلة.':'غير موزونة بعد: عدّل معاملات المواد دون تغيير صيغها الكيميائية.';status.style.color=t.balanced?'var(--green)':'var(--red)'}document.querySelectorAll('[data-rx-i]').forEach(b=>b.onclick=()=>{const cs=rxCoeffs(),i=+b.dataset.rxI;cs[i]=Math.max(1,Math.min(9,cs[i]+Number(b.dataset.rxStep)));refreshReactionNumbers()})}
