atomSceneNew=function(){const x=atomIdentity();return `<div class="model-card atom-model-card ar-upgraded" id="modelCard"><canvas id="atomCanvas" class="atom-3d-canvas" aria-label="تمثيل ثلاثي الأبعاد للذرة ${x.name}"></canvas><div class="model-stage" id="atomFallback">${atomFallbackMarkup()}</div><div class="atom-isotope-badge" id="atomNuclideBadge"><span class="nuclide-num"><sup>${x.a}</sup><sub>${x.z}</sub></span><strong>${x.symbol}</strong><small>${x.sign==='0'?'متعادلة':`شحنة ${x.sign}`}</small></div><div class="zoom-controls"><button id="zoomIn" title="تكبير">+</button><button id="zoomOut" title="تصغير">−</button><button id="resetModel" title="إعادة">↻</button></div><div class="atom-model-label" id="atomLiveLabel"><strong>${x.name} · ${x.symbol}</strong><small>${state.protons} بروتون · ${state.neutrons} نيوترون · ${state.electrons} إلكترون</small></div><div class="atom-ar-action"><button class="primary-btn" id="startAtomAR" type="button"><i class="fa-solid fa-cube"></i> عرض الواقع المعزز</button><small id="atomARSupport" hidden></small></div></div>`};
/* واجهة AR خاصة بربط النماذج الجزيئية بسطح حقيقي، لا كاميرا وهمية. */
function chemARLayer(){let ui=document.getElementById('chemARUI');if(ui)return ui;ui=document.createElement('div');ui.id='chemARUI';ui.className='chem-ar-ui';ui.setAttribute('aria-hidden','true');ui.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><strong id="chemARTitle">النموذج الجزيئي</strong><button id="chemAREnd">إنهاء AR</button></div><div><p id="chemARHint" style="margin:0 0 10px">وجّه الهاتف إلى سطح ثم المس المكان لتثبيت المجسم.</p><div class="reaction-controls"><button id="chemARSmaller">تصغير −</button><button id="chemARLarger">تكبير +</button></div></div>`;document.body.appendChild(ui);ui.addEventListener('beforexrselect',e=>{if(e.target.closest('button'))e.preventDefault()});ui.querySelector('#chemAREnd').onclick=()=>chemXRSession?.end();ui.querySelector('#chemARSmaller').onclick=()=>chemXRScale=Math.max(.4,chemXRScale-.1);ui.querySelector('#chemARLarger').onclick=()=>chemXRScale=Math.min(2.2,chemXRScale+.1);return ui}
async function chemStartAR(){if(!chemGPU){showToast('العرض','تعذر تهيئة المجسم على هذا الجهاز.');return}if(!window.isSecureContext||!navigator.xr){showToast('الواقع المعزز','يحتاج Chrome على هاتف متوافق ورابط HTTPS.');return}let s=null;try{const ui=chemARLayer();s=await navigator.xr.requestSession('immersive-ar',{requiredFeatures:['local','hit-test'],optionalFeatures:['dom-overlay'],domOverlay:{root:ui}});chemXRSession=s;const gl=chemGPU.gl;if(gl.makeXRCompatible)await gl.makeXRCompatible();s.updateRenderState({baseLayer:new XRWebGLLayer(s,gl)});chemXRRef=await s.requestReferenceSpace('local');const viewer=await s.requestReferenceSpace('viewer');chemXRHit=await s.requestHitTestSource({space:viewer});chemXRPlaced=null;chemXRHitPose=null;chemXRScale=1;s.addEventListener('select',()=>{if(chemXRHitPose){chemXRPlaced=Array.from(chemXRHitPose.transform.matrix);ui.querySelector('#chemARHint').textContent='تم تثبيت المجسم. المس موضعًا آخر لإعادة وضعه.'}});s.addEventListener('end',chemAREnd);ui.classList.add('active');ui.setAttribute('aria-hidden','false');ui.querySelector('#chemARTitle').textContent=CHEM_MODELS[chemCurrentKey()].name;if(chemRAF){cancelAnimationFrame(chemRAF);chemRAF=0}s.requestAnimationFrame(chemARFrame)}catch(err){showToast('تعذّر الواقع المعزز',String(err?.message||err).slice(0,110),4600);if(s){try{await s.end()}catch{}}else chemAREnd()}}
function chemARFrame(_,frame){const s=frame.session;if(!chemXRSession||chemXRSession!==s||!chemGPU)return;s.requestAnimationFrame(chemARFrame);const gl=chemGPU.gl,layer=s.renderState.baseLayer,pose=frame.getViewerPose(chemXRRef);if(!pose)return;gl.bindFramebuffer(gl.FRAMEBUFFER,layer.framebuffer);gl.enable(gl.DEPTH_TEST);gl.disable(gl.CULL_FACE);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);try{const res=frame.getHitTestResults(chemXRHit);chemXRHitPose=res?.length?res[0].getPose(chemXRRef):null}catch{chemXRHitPose=null}for(const v of pose.views){const vp=layer.getViewport(v);gl.viewport(vp.x,vp.y,vp.width,vp.height);const key=chemCurrentKey(),m=CHEM_MODELS[key];if(chemXRPlaced){const radius=m.atoms.length>8?.11:.23,anchor=chemMm(chemXRPlaced,chemMm(chemTr(0,.25*chemXRScale,0),chemSc(radius*chemXRScale,radius*chemXRScale,radius*chemXRScale)));chemDrawMolecule(chemGPU,v.projectionMatrix,v.transform.inverse.matrix,anchor,key)}if(chemXRHitPose){const anchor=chemMm(Array.from(chemXRHitPose.transform.matrix),chemSc(.9,.9,.9));chemDrawMolecule(chemGPU,v.projectionMatrix,v.transform.inverse.matrix,anchor,key,true)}}}
function chemAREnd(){chemXRSession=null;chemXRRef=null;chemXRHit=null;chemXRHitPose=null;chemXRPlaced=null;const ui=document.getElementById('chemARUI');if(ui){ui.classList.remove('active');ui.setAttribute('aria-hidden','true')}if(chemGPU&&document.getElementById('chemCanvas')&&!chemRAF)chemDraw()}
/* رسم احتياطي تفاعلي عند منع WebGL: نفس الكرات والوصلات دون ادعاء AR. */
function chemStartFallback(){const canvas=document.getElementById('chemCanvas');if(!canvas)return;const ctx=canvas.getContext('2d');if(!ctx){document.getElementById('chemFallback').style.display='flex';return}let pointer=null;canvas.addEventListener('pointerdown',e=>{pointer={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId)return;state.chemAngle.y+=(e.clientX-pointer.x)*.013;state.chemAngle.x+=(e.clientY-pointer.y)*.013;pointer={id:e.pointerId,x:e.clientX,y:e.clientY}});['pointerup','pointercancel'].forEach(ev=>canvas.addEventListener(ev,()=>pointer=null));canvas.addEventListener('wheel',e=>{e.preventDefault();state.chemAngle.zoom=Math.min(1.9,Math.max(.6,state.chemAngle.zoom+(e.deltaY<0?.09:-.09)))},{passive:false});chemGPU={fallback:true,canvas,ctx};chemDrawFallback()}
function chemDrawFallback(){if(!chemGPU?.fallback||chemXRSession||!document.getElementById('chemCanvas'))return;const {canvas,ctx}=chemGPU,d=Math.min(2,window.devicePixelRatio||1),r=canvas.getBoundingClientRect(),w=Math.max(1,Math.round(r.width*d)),h=Math.max(1,Math.round(r.height*d));if(w!==canvas.width||h!==canvas.height){canvas.width=w;canvas.height=h}ctx.setTransform(1,0,0,1,0,0);const bg=ctx.createRadialGradient(w*.5,h*.3,10,w*.5,h*.5,w*.65);bg.addColorStop(0,'#125d62');bg.addColorStop(1,'#0b1d33');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);
 const key=chemCurrentKey(),m=CHEM_MODELS[key],wide=m.atoms.length>8||key.endsWith('Before')||key.endsWith('After'),s=Math.min(w/(wide?10.5:5.9),h/5)*state.chemAngle.zoom,ay=state.chemAngle.y,ax=state.chemAngle.x;
 function project([x,y,z]){const cy=Math.cos(ay),sy=Math.sin(ay),cx=Math.cos(ax),sx=Math.sin(ax);const u=x*cy+z*sy,zz=-x*sy+z*cy,v=y*cx-zz*sx,depth=y*sx+zz*cx,k=1+depth*.035;return {x:w/2+u*s*k,y:h/2-v*s*k,z:depth}}
 const pts=m.atoms.map(a=>project(a.slice(1)));ctx.lineCap='round';
 for(const [i,j,count] of m.bonds){const a=pts[i],b=pts[j];if(!a||!b)continue;const vx=b.x-a.x,vy=b.y-a.y,len=Math.hypot(vx,vy)||1;for(let k=0;k<count;k++){const offset=(k-(count-1)/2)*7*d;ctx.beginPath();ctx.strokeStyle='#d9dee3';ctx.lineWidth=5*d;ctx.moveTo(a.x-vy/len*offset,a.y+vx/len*offset);ctx.lineTo(b.x-vy/len*offset,b.y+vx/len*offset);ctx.stroke()}}
 m.atoms.map((atom,i)=>({atom,p:pts[i]})).sort((a,b)=>a.p.z-b.p.z).forEach(({atom,p})=>{const el=atom[0],rgb=(CHEM_COLORS[el]||[.6,.78,.73]).map(v=>Math.round(v*255)),r=(el==='H'?.28:el==='Na'?.26:.41)*s,grad=ctx.createRadialGradient(p.x-r*.34,p.y-r*.39,r*.04,p.x,p.y,r);grad.addColorStop(0,'#ffffff');grad.addColorStop(.24,`rgb(${rgb.join(',')})`);grad.addColorStop(1,`rgb(${rgb.map(x=>Math.floor(x*.40)).join(',')})`);ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fillStyle=grad;ctx.fill();ctx.lineWidth=.8*d;ctx.strokeStyle='#ffffff44';ctx.stroke()});chemRAF=requestAnimationFrame(chemDrawFallback)}
/* توفير العارض الاحتياطي دون إلغاء الجلسة الحقيقية على الأجهزة الداعمة. */
chemDestroy=function(){if(chemRAF)cancelAnimationFrame(chemRAF);chemRAF=0;chemPointer=null;if(chemGPU&&!chemXRSession&&!chemGPU.fallback){try{chemGPU.gl.getExtension('WEBGL_lose_context')?.loseContext()}catch{}}chemGPU=null};
chemMount=function(){const c=document.getElementById('chemCanvas');if(!c)return;try{chemGPU=chemCreateGL(c);c.addEventListener('pointerdown',e=>{chemPointer={id:e.pointerId,x:e.clientX,y:e.clientY};c.setPointerCapture?.(e.pointerId)});c.addEventListener('pointermove',e=>{if(!chemPointer||chemPointer.id!==e.pointerId)return;state.chemAngle.y+=(e.clientX-chemPointer.x)*.012;state.chemAngle.x+=(e.clientY-chemPointer.y)*.012;chemPointer.x=e.clientX;chemPointer.y=e.clientY});['pointerup','pointercancel','lostpointercapture'].forEach(t=>c.addEventListener(t,()=>chemPointer=null));c.addEventListener('wheel',e=>{e.preventDefault();state.chemAngle.zoom=Math.max(.6,Math.min(1.9,state.chemAngle.zoom+(e.deltaY<0?.08:-.08)))},{passive:false});chemDraw()}catch(e){chemStartFallback()}};
const chemStartARActual=chemStartAR;
chemStartAR=async function(){if(chemGPU?.fallback){showToast('الواقع المعزز','WebGL غير متوفر على هذا المتصفح؛ جرّب هاتفًا متوافقًا مع WebXR.');return}return chemStartARActual()};
/* عند اختيار عنصر من الجدول حُدِّد نظير مرجعي معلوم بدل تقريب النيوترونات. */
